def apply_visual_feedback(self, element, analysis):
    # Your instinct is right - opacity layers work better
    self.driver.execute_script("""
        // Create overlay div instead of modifying original
        const rect = arguments[0].getBoundingClientRect();
        const overlay = document.createElement('div');
        overlay.className = 'llm-overlay';
        overlay.style.cssText = `
            position: fixed;
            top: ${rect.top}px;
            left: ${rect.left}px;
            width: ${rect.width}px;
            height: ${rect.height}px;
            background: rgba(0, 255, 0, ${arguments[1].confidence * 0.3});
            pointer-events: none;
